import { el,btn,field,select,panel,row,grid,table,dialog,ready } from '../ops-ui.js';
const api=await ready('ProjectDesk'),M=window.ProjectModel;
const form=document.getElementById('issue-form');form.elements.tracker.add(new Option('里程碑','milestone'));const recurrence=field('重复间隔（自然日，0 不重复）','number','0');recurrence.input.name='recurrenceDays';recurrence.input.min=0;recurrence.input.max=3650;recurrence.input.defaultValue='0';form.querySelector('.form-grid').append(recurrence.label);
const p=panel('依赖排期、基线与批量操作','前置任务关系沿用任务详情中的“先于 / 阻塞”，增加循环和排期检查。最长依赖链按自然日估算，不自动调整日期，不考虑周末、人员资源或真正的多人同步。');
const project=select('项目',[]),source=select('前置任务',[]),target=select('后续任务',[]),baselineName=field('基线名称'),baseline=select('比较基线',[]),bulkStatus=select('批量状态',[['','不修改'],['new','新建'],['doing','进行中'],['blocked','受阻'],['resolved','已解决'],['closed','已关闭']]),assignee=field('批量负责人（空白不修改）'),due=field('批量截止日期（空白不修改）','date');
const findings=el('div'),list=el('div'),comparison=el('div'),status=el('p','',{class:'ops-status',role:'status'});let selected=new Set();
p.append(grid(project.label,source.label,target.label),row(btn('添加前置依赖',()=>{if(!source.input.value||!target.input.value)throw Error('选择前置与后续任务');api.update(d=>M.addRelation(d,source.input.value,target.input.value,'precedes'));render()},'primary')),findings,grid(baselineName.label,baseline.label),row(btn('保存当前排期基线',()=>{api.update(d=>M.captureBaseline(d,project.input.value,baselineName.input.value));render()}),btn('删除选中基线',()=>{if(!baseline.input.value||!confirm('删除这份基线？现有任务不受影响，建议先下载备份。'))return;api.update(d=>d.baselines=d.baselines.filter(b=>b.id!==baseline.input.value));render()})),comparison,grid(bulkStatus.label,assignee.label,due.label),row(btn('选择本项目全部任务',()=>{selected=new Set(api.state().issues.filter(i=>i.projectId===project.input.value).map(i=>i.id));render()}),btn('清空选择',()=>{selected.clear();render()}),btn('预览批量修改',previewBulk,'primary')),status,list);
project.input.addEventListener('change',()=>{selected.clear();render()});baseline.input.addEventListener('change',compare);
function compare(){const d=api.state(),b=(d.baselines||[]).find(b=>b.id===baseline.input.value);comparison.replaceChildren();if(!b)return;const rows=b.items.map(r=>{const i=d.issues.find(i=>i.id===r.id);return[r.subject,r.startDate||'—',i?.startDate||'已删除',r.dueDate||'—',i?.dueDate||'已删除',i?(i.startDate!==r.startDate||i.dueDate!==r.dueDate?'排期已变更':'未变化'):'任务已删除']});const saved=new Set(b.items.map(i=>i.id));d.issues.filter(i=>i.projectId===b.projectId&&!saved.has(i.id)).forEach(i=>rows.push([i.subject,'—',i.startDate,'—',i.dueDate,'基线后新增']));comparison.append(table(['任务','基线开始','当前开始','基线截止','当前截止','变化'],rows));}
function render(){const d=api.state(),old=project.input.value||api.selected();project.input.replaceChildren(new Option('选择项目',''));d.projects.forEach(p=>project.input.add(new Option(p.name,p.id)));project.input.value=old;const issues=d.issues.filter(i=>i.projectId===project.input.value);for(const f of[source,target]){const value=f.input.value;f.input.replaceChildren(new Option('选择任务',''));issues.forEach(i=>f.input.add(new Option('#'+i.number+' '+i.subject,i.id)));f.input.value=value;}const oldBaseline=baseline.input.value;baseline.input.replaceChildren(new Option('选择基线',''));(d.baselines||[]).filter(b=>b.projectId===project.input.value).forEach(b=>baseline.input.add(new Option(b.name,b.id)));baseline.input.value=oldBaseline;
  findings.replaceChildren();if(project.input.value){const result=M.schedule(d,project.input.value);findings.append(el('h3',`最长依赖链 · 估算 ${result.days} 自然日`),el('p',result.chain.map(id=>{const i=d.issues.find(i=>i.id===id);return'#'+i.number+' '+i.subject}).join(' → ')||'暂无任务'),table(['排期与状态提醒'],result.warnings.map(s=>[s])));}
  selected=new Set([...selected].filter(id=>issues.some(i=>i.id===id)));status.textContent=`已选 ${selected.size} 条。批量变更会先校验全部任务；存储失败不会只更新一部分。`;
  list.replaceChildren(table(['选择','任务','状态','截止','重复间隔','操作'],issues.map(i=>{const check=el('input',null,{type:'checkbox',checked:selected.has(i.id)});check.addEventListener('change',()=>{check.checked?selected.add(i.id):selected.delete(i.id);status.textContent=`已选 ${selected.size} 条`});return[check,'#'+i.number+' '+i.subject,i.status,i.dueDate||'—',i.recurrenceDays?`${i.recurrenceDays} 天`:'不重复',row(btn('编辑',()=>api.openIssue(i.id)),btn('生成下一期',()=>{api.update(d=>M.repeatIssue(d,i.id));render()}))]})));compare();
}
function previewBulk(){const ids=[...selected];if(!ids.length)throw Error('先选择任务');const before=api.state(),next=JSON.parse(JSON.stringify(before));function change(data){for(const id of ids){const i=data.issues.find(i=>i.id===id);if(!i)throw Error('任务已删除');M.upsertIssue(data,{...i,status:bulkStatus.input.value||i.status,assignee:assignee.input.value.trim()||i.assignee,dueDate:due.input.value||i.dueDate},id)}}change(next);M.validate(next);const d=dialog('批量变更预览');d.append(table(['任务','状态','负责人','截止'],next.issues.filter(i=>ids.includes(i.id)).map(i=>[i.subject,i.status,i.assignee||'未指派',i.dueDate||'—'])),row(btn('确认应用',()=>{if(JSON.stringify(api.state())!==JSON.stringify(before))throw Error('项目数据已变化，请重新预览');api.update(data=>{data.issues=next.issues;data.activity=next.activity;data.seq=next.seq});d.close();render()},'primary'),btn('取消',()=>d.close())));d.showModal()}
let timer;window.addEventListener('yj-project-update',()=>{clearTimeout(timer);timer=setTimeout(render,100)});render();
